def quicksort(xs):
    def sort(lo, hi):
        if lo >= hi:
            return
        r = random.randint(lo, hi)
        xs[r], xs[hi] = xs[hi], xs[r]
        p = partition(xs, lo, hi)
        sort(lo, p - 1)
        sort(p + 1, hi)
    sort(0, len(xs) - 1)

