import random


def partition(xs, lo, hi):
    pivot = xs[hi]
    i = lo
    for j in range(lo, hi):
        if xs[j] <= pivot:
            xs[i], xs[j] = xs[j], xs[i]
            i += 1
    xs[i], xs[hi] = xs[hi], xs[i]
    return i


def quickselect(xs, k):
    lo, hi = 0, len(xs) - 1
    while lo < hi:
        r = random.randint(lo, hi)
        xs[r], xs[hi] = xs[hi], xs[r]
        p = partition(xs, lo, hi)
        if k == p:
            return xs[p]
        if k < p:
            hi = p - 1
        else:
            lo = p + 1
    return xs[lo]
